// Psalms: book six, and the first book in the app that is poetry from end to end.
//
// The scripture is never typed here. Every verse, line break and heading comes from
// content/psalms-text.ts, generated by scripts/build-psalms-text.ts and proven against the BSB.
// This file decides only how the 150 psalms are grouped into readings and movements, and it is
// where the commentary for each reading is layered on, movement by movement, as it is written.
//
// The commentary lives in content/psalms-notes/, keyed by reading id, and is laid over the text
// here. Until a psalm is authored it reads at the plain tier: the lineated text and nothing more,
// under the BSB's own section title as a working title. See .scratch/psalms/spec.md.
//
// The book is unpublished until all five movements are written, exactly as every book before it
// was: reachable by direct URL, absent from the landing page and the find index.
import { PSALM_NOTES } from "@/content/psalms-notes";
import { PSALMS_TEXT, PSALM_119_LETTERS } from "@/content/psalms-text";
import type { Movement, Panel, Passage, Reading } from "@/lib/types";

// One psalm as a single poem passage, authored whole (ADR 0001).
function psalmPassage(
  chapter: number,
  from = 1,
  to?: number,
  title?: string,
): Passage {
  const text = PSALMS_TEXT[chapter];
  const verses = text.verses.filter(
    (v) => v.n >= from && v.n <= (to ?? Number.POSITIVE_INFINITY),
  );
  const last = verses[verses.length - 1].n;
  return {
    ref: `${chapter}:${from}–${last}`,
    kind: "poem",
    form: "poetry",
    title: title ?? text.title,
    ...(from === 1 && text.superscription
      ? { superscription: text.superscription }
      : {}),
    verses,
  };
}

// Two psalms that are one poem divided by a later chapter break: Psalms 9–10 run an acrostic
// across both, and 42–43 share a refrain ("Why are you downcast, O my soul?").
const JOINED: Record<number, number> = { 9: 10, 42: 43 };

// Psalm 119 is 176 verses in 22 stanzas, one for each letter of the Hebrew alphabet. It reads as
// four sittings of five or six stanzas, each stanza its own passage under its letter.
const PSALM_119_READINGS: { id: string; stanzas: [number, number] }[] = [
  { id: "ps-119a", stanzas: [0, 4] },
  { id: "ps-119b", stanzas: [5, 10] },
  { id: "ps-119c", stanzas: [11, 15] },
  { id: "ps-119d", stanzas: [16, 21] },
];

const titleCase = (s: string) =>
  s
    .toLowerCase()
    .replace(/(^|\s)\p{L}/gu, (c) => c.toUpperCase())
    .replace(/ And /g, " and ");

function plainReadings(): Reading[] {
  const readings: Reading[] = [];
  const joinedTail = new Set(Object.values(JOINED));
  for (let c = 1; c <= 150; c++) {
    if (joinedTail.has(c)) continue;
    if (c === 119) {
      for (const { id, stanzas } of PSALM_119_READINGS) {
        const passages = PSALM_119_LETTERS.slice(
          stanzas[0],
          stanzas[1] + 1,
        ).map((s) =>
          psalmPassage(119, s.before, s.before + 7, titleCase(s.letter)),
        );
        const first = passages[0].verses?.[0].n;
        const last = passages[passages.length - 1].verses?.slice(-1)[0].n;
        readings.push({
          id,
          bookId: "psalms",
          tier: "plain",
          span: `Psalm 119:${first}–${last}`,
          chapterIndex: 119,
          title: PSALMS_TEXT[119].title,
          passages,
        });
      }
      continue;
    }
    const tail = JOINED[c];
    readings.push({
      id: `ps-${c}`,
      bookId: "psalms",
      tier: "plain",
      span: tail ? `Psalms ${c}–${tail}` : `Psalm ${c}`,
      chapterIndex: c,
      ...(tail ? { crossesChapters: true } : {}),
      title: PSALMS_TEXT[c].title,
      passages: tail
        ? [psalmPassage(c), psalmPassage(tail)]
        : [psalmPassage(c)],
    });
  }
  return readings;
}

// Lays a reading's authored notes over its text. A single-psalm reading's passage takes the
// reading's title; a passage of a joined pair or a stanza of Psalm 119 keeps its own unless the
// notes name one.
function withNotes(reading: Reading): Reading {
  const notes = PSALM_NOTES[reading.id];
  if (!notes) return reading;
  if (notes.passages.length !== reading.passages.length)
    throw new Error(
      `${reading.id}: notes cover ${notes.passages.length} passage(s), the reading has ${reading.passages.length}`,
    );
  const single = reading.passages.length === 1;
  return {
    ...reading,
    tier: notes.tier,
    title: notes.title,
    ...(notes.thread ? { thread: notes.thread } : {}),
    ...(notes.closeEnd ? { closeEnd: notes.closeEnd } : {}),
    passages: reading.passages.map((passage, i) => ({
      ...passage,
      ...(single ? { title: notes.title } : {}),
      ...notes.passages[i],
    })),
  };
}

export const PSALMS: Reading[] = plainReadings().map(withNotes);

